    ts.className = 'msg-timestamp';
    ts.textContent = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    const wrapper = document.createElement('div');
    wrapper.appendChild(bubble);
    wrapper.appendChild(ts);

    msg.appendChild(avatar);
    msg.appendChild(wrapper);
    messagesEl.appendChild(msg);
    messagesEl.scrollTop = messagesEl.scrollHeight;
    return bubble;
  }

  function copyMessage(text, btn) {
    navigator.clipboard.writeText(text).then(() => {
      const originalText = btn.textContent;
      btn.textContent = 'Copied!';
      btn.classList.add('copied');
      setTimeout(() => {
        btn.textContent = originalText;
        btn.classList.remove('copied');
      }, 2000);
    }).catch(err => {
      console.error('Failed to copy:', err);
    });
  }

  function downloadConversation() {
    if (conversationHistory.length === 0) {
      alert('No conversation to download yet!');
      return;
    }

    // Build markdown format
    let markdown = '# Safecast Radiation Assistant Conversation\n\n';
    markdown += `Date: ${new Date().toLocaleString()}\n\n`;
    markdown += '---\n\n';

    conversationHistory.forEach(msg => {
      const role = msg.role === 'user' ? 'You' : 'Assistant';
      markdown += `## ${role}\n\n`;
      markdown += msg.content + '\n\n';
      markdown += '---\n\n';
    });

    // Create download link
    const blob = new Blob([markdown], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `safecast-conversation-${new Date().toISOString().slice(0,10)}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  function clearConversation() {
    // Clear conversation history
    conversationHistory = [];

    // Clear all messages
    while (messagesEl.firstChild) {
      messagesEl.removeChild(messagesEl.firstChild);
    }

    // Show intro again
    messagesEl.appendChild(introEl);
    introEl.style.display = 'block';

    // Focus on input
    msgEl.focus();
  }

  function sendFeedback(chatID, score, upBtn, downBtn) {
    fetch('/api/feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatID, score }),
    }).catch(() => {}); // fire-and-forget

    upBtn.disabled = true;
    downBtn.disabled = true;
    const row = upBtn.parentElement;
    row.classList.add('voted');
    if (score > 0) upBtn.classList.add('active');
    else downBtn.classList.add('active');
  }

  function addFeedbackRow(wrapper, chatID, isCached) {
    const row = document.createElement('div');
    row.className = 'feedback-row';

    if (isCached) {
      const badge = document.createElement('span');
      badge.className = 'cached-badge';
      badge.textContent = '⚡ cached';
      badge.title = 'This answer came from the semantic cache';
      row.appendChild(badge);
    }

    const upBtn = document.createElement('button');
    upBtn.className = 'feedback-btn up';
    upBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3H14z"/><path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg>';
    upBtn.title = 'Helpful';

    const downBtn = document.createElement('button');
    downBtn.className = 'feedback-btn down';
    downBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3H10z"/><path d="M17 2h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17"/></svg>';
    downBtn.title = 'Not helpful';

    upBtn.onclick   = () => sendFeedback(chatID, 1,  upBtn, downBtn);
    downBtn.onclick = () => sendFeedback(chatID, -1, upBtn, downBtn);

    row.appendChild(upBtn);
    row.appendChild(downBtn);
    wrapper.appendChild(row);
  }

  function sendMessage(text) {
    busy = true;
    sendBtn.disabled = true;

    addMessage('user', text);
    const botBubble = addMessage('bot', '…thinking…', 'thinking');

    let accumulated = '';
    let chatID = 0;
    let isCached = false;
    let finished = false;

    function finish(success = true) {
      if (finished) return;
      finished = true;
      botBubble.classList.remove('thinking');
      busy = false;
      sendBtn.disabled = false;
      msgEl.focus();

      // Display bot response (disclaimer already included in _ai_generated_note from backend)
      if (success && accumulated) {
        botBubble.innerHTML = markdownToHTML(accumulated);

        // Re-add copy button
        const copyBtn = document.createElement('button');
        copyBtn.className = 'copy-btn';
        copyBtn.textContent = 'Copy';
        copyBtn.onclick = () => copyMessage(accumulated, copyBtn);
        botBubble.appendChild(copyBtn);

        conversationHistory.push(
          { role: 'user', content: text },
          { role: 'assistant', content: accumulated }
        );

        // Keep only last 10 messages (5 exchanges) to prevent rate limits
        const MAX_HISTORY = 10;
        if (conversationHistory.length > MAX_HISTORY) {
          conversationHistory = conversationHistory.slice(-MAX_HISTORY);
        }

        // Add thumbs up/down feedback buttons if we have a chat_id
        if (chatID) {
          const wrapper = botBubble.parentElement;
          addFeedbackRow(wrapper, chatID, isCached);
        }
      }
    }

    fetch('/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message: text,
        history: conversationHistory,
        source: 'web-chat',
        client_timestamp: new Date().toISOString()
      }),
    }).then(response => {
      const reader  = response.body.getReader();
      const decoder = new TextDecoder();
      let   buffer  = '';

      function pump() {
        return reader.read().then(({ done, value }) => {
          if (done) { finish(); return; }

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop(); // keep incomplete last line

          for (const line of lines) {
            if (!line.trim()) continue;
            try {
              const ev = JSON.parse(line);
              if (ev.type === 'text') {
                if (botBubble.classList.contains('thinking')) {
                  botBubble.classList.remove('thinking');
                  accumulated = '';
                }
                accumulated += ev.text;
                botBubble.innerHTML = markdownToHTML(accumulated);
                messagesEl.scrollTop = messagesEl.scrollHeight;
              } else if (ev.type === 'done') {
                if (ev.chat_id) { chatID = ev.chat_id; isCached = !!ev.cached; }
                finish();
              } else if (ev.type === 'error') {
                botBubble.classList.remove('thinking');
                botBubble.classList.add('error');
                botBubble.textContent = 'Error: ' + ev.error;
                finish(false);
              }
            } catch { /* malformed line, skip */ }
          }
          return pump();
        });
      }
      return pump();
    }).catch(err => {
      botBubble.classList.remove('thinking');
      botBubble.classList.add('error');
      botBubble.textContent = 'Connection error: ' + err.message;
      finish(false);
    });
  }

  msgEl.focus();
</script>
</body>
</html>

